window.REPORT_PRELOAD_CACHE["ONON.html"] = {"version":"2e4d8114a1dfa2c111925908ff2d52366540fbf0f3566c4f314ca782bebc9272","html":"html_content = \"\"\"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>昂跑 On Holding AG (NYSE: ONON) 深度研究报告：高端运动科技跑鞋崛起、DTC 渠道高增与全球品牌势能扩张</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            onorange: {\n              400: '#FF7A00',\n              500: '#FF5500',\n              600: '#E04800',\n            },\n            accent: {\n              500: '#FF5500',\n              600: '#E04800',\n            },\n            teal: {\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(255, 85, 0, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n      border-left: 3px solid #FF5500;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-onorange-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-onorange-500 via-amber-400 to-teal-500 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-onorange-500 to-onorange-600 flex items-center justify-center font-extrabold text-white shadow\">\n        ON\n      </div>\n      <div>\n        <div class=\"text-[11px] text-onorange-400 font-semibold tracking-wider uppercase\">NYSE: ONON · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">昂跑 On Holding 深度研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">ONON 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构拆解</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 品牌势能与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 运动鞋服同行竞争对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球高端运动与消费品牌研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (Q3 2026 / FY26E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-onorange-500 to-onorange-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-onorange-500/25\">\n            ON\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-onorange-400 bg-onorange-500/15 px-2 py-0.5 rounded\">NYSE: ONON</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">昂跑深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          高端运动科技跑鞋崛起 · DTC 渠道高增与全球品牌势能扩张\n        </p>\n      </div>\n\n      <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">Q3 2026 净销售额</span>\n          <span class=\"font-mono font-bold text-white\">CHF 931.4M <span class=\"text-onorange-400\">(+17.2%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">毛利率 (Gross Margin)</span>\n          <span class=\"font-mono font-bold text-teal-400\">72.6% <span class=\"text-slate-400\">(创历史新高)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">全年指引 (FY26)</span>\n          <span class=\"font-mono font-bold text-onorange-400\">CHF 3.47B–3.56B (+20%)</span>\n        </div>\n      </div>\n\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-onorange-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构拆解</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>品牌势能与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>运动鞋服同行竞争对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-onorange-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-onorange-500 hover:bg-onorange-600 text-white text-xs font-extrabold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. Hero 研报封面区与执行摘要\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-onorange-500/15 text-onorange-600 dark:text-onorange-400 font-bold border border-onorange-500/30\">评级：强烈买入 / 消费成长核心标的</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026 财年全球门店扩张与鞋服双擎驱动</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>NYSE: ONON</span>\n          </div>\n        </div>\n\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#FF5500 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-onorange-500/20 border border-onorange-500/40 text-onorange-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-onorange-400 animate-pulse\"></span>\n              <span>CORE THESIS · Q3 净销售额历史性首破 CHF 900M × 毛利率攀升至 72.6% × DTC 渠道高增 25%</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              昂跑 On Holding AG (NYSE: ONON) 深度研究报告：高端运动科技跑鞋崛起、DTC 渠道高增与全球品牌势能扩张\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              高端运动品牌昂跑（On）在 2026 年第三季度交出了一份惊艳的财务答卷：单季净销售额同比增长 <strong class=\"text-white\">+17.2%（固定汇率下 +17.8%）达到 CHF 931.4 million</strong>，历史上首次单季突破 9 亿瑞士法郎大关。\n              得益于直营 DTC 渠道强劲增长 <strong class=\"text-onorange-400\">+25.0%（占比升至 42.2%）</strong>以及服装品类爆发式增长 <strong class=\"text-white\">+38.7%</strong>，公司毛利率创下历史新高达到 <strong class=\"text-teal-400\">72.6%</strong>，净利润大增 36.9% 至 CHF 162.8 million。\n            </p>\n\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">单季销售历史突破</div>\n                <div class=\"text-white font-semibold\">Q3 净销售额首次突破 CHF 9 亿（达到 CHF 931.4M），全渠道多点强劲开花</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">盈利能力历史之巅</div>\n                <div class=\"text-onorange-400 font-semibold\">毛利率跃升至 72.6%（去年同期 65.7%），调整后 EBITDA 飙升 42.7% 至 CHF 256.8M</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">全年业绩预期稳健</div>\n                <div class=\"text-teal-400 font-semibold\">预计 FY26 全年按固定汇率计增长在低 20% 区间，绝对销售额约 CHF 3.47B–3.56B</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>Q3 2026 净销售额</span>\n              <span class=\"p-1.5 rounded-lg bg-onorange-500/15 text-onorange-600 dark:text-onorange-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">CHF 931.4M</span>\n              <span class=\"text-xs font-bold text-onorange-600 dark:text-onorange-400 bg-onorange-500/15 px-2 py-0.5 rounded\">+17.2% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              单季销售额首破 9 亿瑞郎大关，各区域、各渠道及各产品线均实现强劲双位数增长。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>Q3 毛利率 (Gross Margin)</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">72.6%</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">同比提升 +6.9 pts</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              得益于 DTC 直营渠道占比扩大（达到 42.2%）及优质全价销售结构，毛利率创下历史新高。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>Q3 调整后 EBITDA 利润率</span>\n              <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">27.6%</span>\n              <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">CHF 256.8M</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              调整后 EBITDA 同比飙升 42.7% 至 CHF 256.8 million，盈利释放速度显著超越营收增速。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>现金储备与净运营资本</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">CHF 1.34B</span>\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">+31.3% 增长</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              截至 2026 年 9 月 30 日，现金及现金等价物增至 CHF 1,339.0M，资产负债表极其强健。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-onorange-600 dark:text-onorange-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构拆解：鞋履基本盘、服装爆发与 DTC 渠道跃升</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">Q3 2026 净销售额 CHF 931.4M · DTC 占比 42.2%</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2022–FY2026E 年度净销售额与渠道演进</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">DTC 直营与全渠道扩张驱动销售额从 CHF 1.2B 迅猛迈向 CHF 3.5B+</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-onorange-600 dark:text-onorange-400 shadow-sm transition\">视图A：年度营收演进</button>\n                <button onclick=\"switchBizChart('q3_split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：Q3 产品与渠道拆解</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"onBizChart\"></canvas>\n            </div>\n          </div>\n\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大核心增长引擎</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-onorange-500/15 text-onorange-600 dark:text-onorange-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">Performance（专业跑步：Cloudsurfer 3 创新周期）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      以跑步为核心的专业鞋履依然是基本盘（Q3 鞋类收入 CHF 843.7M）。随着 Cloudsurfer 3 等史上最大创新周期开启，专业跑鞋在跑步专卖店中广受赞誉。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">Lifestyle（潮流生活：Cloudtilt 现象级单品）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      以运动休闲为引领，Cloudtilt 系列继续保持全球增长最快的运动鞋履系列之一，成功破圈进入高端时尚与日常穿搭消费群体。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">Apparel（服装矩阵：Her 系列与 Zendaya 联名爆发）</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      服装品类 Q3 同比飙升 <strong>+38.7% 达到 CHF 69.5M</strong>。最新 Zendaya 联名与女性专属 Her 系列成为品牌史上最具视觉冲击力且最成功的服装发布。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">渠道结构变革</span>\n              <span class=\"font-bold text-onorange-600 dark:text-onorange-400\">DTC 直营渠道占比提升至 42.2% (+25% YoY)</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <div class=\"md:col-span-2 report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-onorange-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n              <div class=\"flex items-center space-x-2\">\n                <span class=\"px-2.5 py-1 rounded-md bg-onorange-500/15 text-onorange-600 dark:text-onorange-400 text-xs font-bold\">绝对核心底盘 · 占比 90.6%</span>\n                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">+15.4% YoY (Shoes)</span>\n              </div>\n              <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">Q3 鞋履收入：CHF 843.7M</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 鞋履产品线（Shoes：专业跑步与潮流休闲双轮驱动）</h3>\n            <div class=\"mt-3 grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">专业跑步矩阵升级</div>\n                <p class=\"leading-relaxed\">\n                  CloudTec 专利缓震科技不断迭代，Cloudsurfer 3 及专业马拉松竞速系列在跑步专业垂直领域建立极高专业口碑。\n                </p>\n              </div>\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">时尚潮流破圈</div>\n                <p class=\"leading-relaxed\">\n                  Cloudtilt 和日常休闲鞋款将运动科技与都市美学完美结合，成功吸引大量年轻潮流消费者及都市白领日常穿着。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">高成长第二曲线 · +38.7%</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">CHF 69.5M</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. 服装品类（Apparel）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                服装品类展现出惊人的爆发力，同比大增 38.7%。女性运动服饰“Her”系列与 Zendaya 联名款发布大获成功，显著提升了客单价和品牌整体调性。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n              Zendaya 联名款引爆市场\n            </div>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">配件矩阵 · +39.2%</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">CHF 18.1M</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. 配件品类（Accessories）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                包括专业运动袜、帽子、背包等周边配件，Q3 延续高速增长态势（+39.2%），进一步完善了昂跑运动生活方式（Lifestyle）生态闭环。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold\">\n              生态配套协同率提升\n            </div>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">直营渠道 · 占比 42.2%</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">CHF 393.3M</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. DTC 直营渠道（Direct-to-Consumer）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                DTC 渠道销售额同比大增 <strong>+25.0%</strong>，占总销售额比例提升至 42.2%。全球旗舰店扩张与精细化私域运营有效增厚了毛利率。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n              直营增速 +25% · 毛利核心驱动\n            </div>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-slate-400 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-slate-500/10 text-slate-600 dark:text-slate-400 text-xs font-bold\">批发渠道 · 稳健压舱石</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">全球精选专卖店</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">5. 批发渠道（Wholesale）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                通过与全球顶级精选体育用品零售商（Run Specialty）和高端百货合作，批发渠道保持稳健增长，为品牌在全球市场快速铺货提供坚实基础。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n              精选跑鞋专卖网络深度覆盖\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 品牌势能与四重核心护城河\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Brand Momentum & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 品牌势能与四重核心护城河：瑞士科技基因、差异化美学与全价销售</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：宽 (Wide Moat · 高端运动科技与时尚生活破圈者)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-onorange-500/15 text-onorange-600 dark:text-onorange-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">CloudTec® 专利缓震科技与瑞士基因</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                源自瑞士苏黎世的高端运动科技，标志性的“空心云块”结构（CloudTec）兼具极佳的落地缓冲与强劲蹬地回弹，构筑了硬核的产品功能壁垒。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">卓越的全价销售与极低折扣率</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                凭借高品牌势能与严格的渠道价格管控，昂跑绝大部分产品以全价（Full Price）售出，毛利率高达 72.6%，远超传统运动品牌平均水平。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">专业运动与都市时尚的双向破圈</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                成功打通“硬核马拉松跑者”与“都市时尚白领”两个原本割裂的消费圈层，兼具运动功能性与日常穿搭美学。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球明星代言与顶级赛事矩阵</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                网坛传奇罗杰·费德勒（Roger Federer）作为股东深度参与，叠加赞助顶尖长跑运动员及全球现象级时尚联名（如 Zendaya），持续拉高品牌声量。\n              </p>\n            </div>\n          </div>\n\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">高端运动鞋服品牌五维护城河量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">On (昂跑) vs Hoka vs Lululemon vs Nike（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"onMoatRadar\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-onorange-600 dark:text-onorange-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 运动鞋服同行竞争横向对比：高端跑鞋双雄与传统巨头博弈</h2>\n          </div>\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-onorange-500 text-white shadow-sm transition\">全部阵营</button>\n            <button onclick=\"filterCompetitors('running')\" data-filter=\"running\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">高端专业跑鞋对手</button>\n            <button onclick=\"filterCompetitors('sport')\" data-filter=\"sport\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">传统运动与瑜伽巨头</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心品牌</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">核心科技与定位</th>\n                  <th class=\"py-4 px-4 min-w-[140px]\">渠道战略与 DTC 占比</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">毛利率水平</th>\n                  <th class=\"py-4 px-4 min-w-[115px]\">年营收增速</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞合关系评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <tr data-category=\"core\" class=\"bg-onorange-500/5 dark:bg-onorange-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-onorange-500 text-white text-[10px] font-extrabold\">高成长标杆</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">On (昂跑 ONON)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">CloudTec® 缓震 · 瑞士高端运动科技</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">瑞士高端运动科技与时尚生活</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">DTC 占比 42.2% 且加速扩张</td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~72.6%</td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-onorange-600 dark:text-onorange-400\">+17% 至 +20%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>高端破圈先锋：</strong>兼具专业跑步与都市时尚势能，全价销售比例高，毛利率在运动鞋服行业处于绝对头部。\n                  </td>\n                </tr>\n\n                <tr data-category=\"running\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Hoka (Deckers旗下)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">厚底缓震 · 专业长跑与越野跑</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">极致厚底缓震与专业越野</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">批发为主 + 稳健 DTC 扩张</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~60% - 64%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">+15% - 25%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>昂跑最大直接对手：</strong>在专业马拉松与越野跑者中极具统治力，凭借厚底舒适度与昂跑在高端专业跑鞋市场形成双雄对峙。\n                  </td>\n                </tr>\n\n                <tr data-category=\"sport\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Lululemon (露露乐蒙)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">高端瑜伽生活方式 · 进军鞋履</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-sky-500/15 text-sky-700 dark:text-sky-400\">高净值社群与运动生活美学</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">高纯度 DTC 直营体系</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~58% - 60%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">+10% - 12%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>高端社群标杆：</strong>在女性运动服饰和社群运营上无出其右，近年来切入鞋履赛道与昂跑在都市生活方式场景产生正面交集。\n                  </td>\n                </tr>\n\n                <tr data-category=\"sport\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Nike (耐克)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">全球运动巨头 · 全品类覆盖</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">全品类大众体育与巨额营销</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">批发与 DTC 混合平衡</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~44% - 46%</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">低个位数 / 周期调整</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>体量庞大的行业巨头：</strong>凭借绝对领先的全球分销网络和体育明星代言占据大众心智，但在高端跑鞋垂直创新和时尚潮流感上近年来受到新兴品牌分流。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值体系解析\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与估值体系：72.6% 顶级毛利率与现金流大幅充实</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">现金储备 CHF 1.34B · 盈利能力全线超预期</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-onorange-600 dark:text-onorange-400 uppercase\">Gross Profit Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">72.6% (Q3)</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              受 DTC 渠道占比提升（42.2%）与全价销售拉动，单季毛利率同比大幅跃升 6.9 个百分点至历史巅峰。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Net Income (Q3)</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">CHF 162.8M</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              Q3 净利润同比大增 36.9%（去年同期 CHF 118.9M），净利润率提升至 17.5%，盈利转化效率惊艳。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Cash & Cash Equivalents</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">CHF 1.34B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              截至 2026 年 9 月底，现金及现金等价物较去年底大幅增加 31.3% 至 CHF 1,339.0 million，无长短期偿债压力。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Adjusted EBITDA Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">27.6% (Q3)</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              Q3 调整后 EBITDA 达到 CHF 256.8 million（同比大增 42.7%），利润率从 22.6% 显著提升至 27.6% 稳健区间。\n            </p>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2026E 净销售额与毛利率演进趋势</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">高成长与高毛利并行：受益于 DTC 直营占比持续扩大，毛利率从 60% 稳步跨越至 72% 以上</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-onorange-600 dark:text-onorange-400 bg-onorange-500/10 px-2.5 py-1 rounded\">FY26E 销售额目标 CHF ~3.5B</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"onValuationChart\"></canvas>\n          </div>\n        </div>\n\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">高增长与高毛利双击</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>毛利率突破 72.6% 历史极值：</strong>DTC 直营渠道强劲增长（+25%）与极少折扣的全价销售带来顶级的单品盈利质量。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>服装品类爆发（+38.7%）：</strong>Her 系列与 Zendaya 联名打破“单靠鞋履”的单一结构，打开百亿服装市场增量空间。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>现金流充沛（CHF 1.34B）：</strong>无负债压力且现金储备充裕，为全球核心商圈旗舰店扩张与品牌营销奠定坚实财力。</span></li>\n            </ul>\n          </div>\n\n          <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">估值与海外汇率波动</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>估值溢价较高：</strong>作为高成长消费股，市场赋予其较高的 P/E 预期，任何季度增速未达极致均可能引发股价短期震荡。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>汇率波动敏感性：</strong>作为瑞士公司（以瑞郎报表计价，但美元、欧元及亚太收入占比较大），汇率剧烈波动可能对财务报表折算产生扰动。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>时尚潮流周期风险：</strong>运动休闲鞋服对潮流趋势敏感，需持续依靠强劲研发保持产品生命力。</span></li>\n            </ul>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置框架\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-onorange-600 dark:text-onorange-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与机构风控纪律</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：全球消费成长核心底仓 · 紧盯 DTC 与服装渗透率</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-onorange-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-onorange-500/15 text-onorange-600 dark:text-onorange-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-onorange-600 dark:text-onorange-400\">概率：30%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">驱动估值：DTC 与服装超预期</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>全球核心商圈旗舰店扩张超预期，DTC 占比突破 45%，服装品类保持 40%+ 超高增速，毛利率稳守 72%+，净利润率显著增厚。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-onorange-600 dark:text-onorange-400\">\n              潜在上行空间：+35% 至 +45%\n            </div>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-teal-500/15 text-teal-600 dark:text-teal-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-teal-600 dark:text-teal-400\">概率：55%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">驱动估值：稳健 20%+ 增长</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>FY26 全年销售额如期达成 CHF 3.47B–3.56B 目标（固定汇率下增长约 20%），毛利率维持在 67.5% 稳态，EBITDA 利润率保持 21% 区间。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-teal-600 dark:text-teal-400\">\n              潜在上行空间：+15% 至 +25%（业绩兑现驱动）\n            </div>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：15%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守估值：消费放缓缓冲</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>全球宏观消费降级导致高端运动鞋服需求阶段性放缓，批发渠道库存调整，增速回落至低双位数，估值倍数短期回调。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n              潜在下行回撤：-15% 至 -20%（强劲现金和无负债提供支撑）\n            </div>\n          </div>\n        </div>\n\n        <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n          <h3 class=\"text-base font-bold text-onorange-400 mb-4 flex items-center space-x-2\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n            <span>机构级资产配置与投资组合建议</span>\n          </h3>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-white mb-1\">1. 消费成长核心标的 (Growth Allocation)</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                作为全球高端运动鞋服领域成长势能最猛的黑马品牌，建议在消费与成长组合中保持<strong>标配至超配（Overweight）</strong>。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-onorange-400 mb-1\">2. 逢财报波动或宏观情绪回调加仓</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                利用运动消费板块整体波动带来的预期差，分批吸纳以充分享受昂跑从专业跑鞋向全球生活方式巨头跃迁的红利。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-teal-400 mb-1\">3. 动态跟踪 DTC 与服装品类增速</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                将 DTC 渠道占比（目标 45%+）及服装品类同比增速（目标 35%+）作为核心跟踪指标，监控品牌第二成长曲线的兑现度。\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           六、 季度基本面跟踪 KPI 交互式核查清单\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n          </div>\n          <div class=\"flex items-center space-x-2 no-print\">\n            <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-onorange-500/15 text-onorange-600 dark:text-onorange-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n            <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n            点击勾选机构季报追踪已验证达标的指标（状态自动本地保存），用高频基本面事实动态校准投资逻辑：\n          </p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF5500] focus:ring-onorange-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. DTC 直营渠道增速与占比是否持续扩大</span>\n                  <span class=\"text-[11px] font-mono text-onorange-600 dark:text-onorange-400 font-semibold shrink-0\">渠道结构核心锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  追踪 DTC 渠道单季营收增速（当前 +25.0%）及占总销售额比重（当前 42.2%），评估直营店及电商扩张成效。\n                </p>\n              </div>\n            </label>\n\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF5500] focus:ring-onorange-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 毛利率是否稳守 66%–72% 行业顶尖区间</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">定价权晴雨表</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查 Q3 创下 72.6% 历史新高后，全价销售结构与供应链成本控制的后续稳定性。\n                </p>\n              </div>\n            </label>\n\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF5500] focus:ring-onorange-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 服装与配件品类增速是否维持 35% 以上高增</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">第二增长曲线</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测服装品类（当前 +38.7%）在 Zendaya 联名与 Her 系列带动下的规模扩张和市场接受度。\n                </p>\n              </div>\n            </label>\n\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF5500] focus:ring-onorange-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 亚太区（APAC）及国际市场扩张爆发力</span>\n                  <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">全球化增量指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪亚太地区（Q3 固定汇率下大增 31.9%）及中国市场等新兴区域的门店拓张与品牌渗透进度。\n                </p>\n              </div>\n            </label>\n\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF5500] focus:ring-onorange-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 调整后 EBITDA 利润率维持在 21%–21.5%</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">经营效率指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  评估品牌在进行全球营销投放和旗舰店建设时的费用控制与规模效应兑现能力。\n                </p>\n              </div>\n            </label>\n\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF5500] focus:ring-onorange-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 现金储备与存货周转健康度</span>\n                  <span class=\"text-[11px] font-mono text-sky-600 dark:text-sky-400 font-semibold shrink-0\">资产负债安全垫</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查现金及现金等价物（当前 CHF 1.34B）与净运营资本周转效率，确保无供应链滞销风险。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- 页脚免责声明 -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>昂跑 On Holding AG (NYSE: ONON) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：FY2026 Q3 财报及 2026 年 11 月市场一致预期</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于昂跑公司公开财务报告、运动鞋服行业调研及市场一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的未来业绩预测、全年销售额目标及三情景估值模型均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <script>\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-onorange-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-onorange-400');\n          }\n        }\n      });\n    });\n\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-onorange-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-onorange-500', 'text-white', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    const KPI_STORAGE_KEY = 'onon_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {}\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {}\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    let bizChartInstance = null;\n    let moatRadarInstance = null;\n    let valuationChartInstance = null;\n    let currentBizMode = 'evolution';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('onBizChart').getContext('2d');\n      const colors = getChartColors();\n\n      const evoConfig = {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E'],\n          datasets: [\n            {\n              label: 'DTC 直营渠道 (CHF B)',\n              data: [0.48, 0.65, 0.98, 1.35, 1.62],\n              backgroundColor: '#FF5500',\n              borderRadius: 4,\n            },\n            {\n              label: '批发渠道 (CHF B)',\n              data: [0.74, 1.14, 1.81, 1.66, 1.90],\n              backgroundColor: '#64748B',\n              borderRadius: 4,\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: CHF ${ctx.parsed.y}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              max: 4.0,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => 'CHF ' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      const splitConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            'Q3 鞋履 (Shoes)',\n            'Q3 DTC 直营渠道',\n            'Q3 批发渠道 (Wholesale)',\n            'Q3 服装 (Apparel)',\n            'Q3 配件 (Accessories)'\n          ],\n          datasets: [\n            {\n              label: 'Q3 2026 销售额 (CHF M)',\n              data: [843.7, 393.3, 538.1, 69.5, 18.1],\n              backgroundColor: [\n                '#FF5500',\n                '#06B6D4',\n                '#3B82F6',\n                '#6366F1',\n                '#64748B'\n              ],\n              borderRadius: 6,\n              barThickness: 24\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `销售额: CHF ${ctx.parsed.x}M`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 950,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => 'CHF ' + v + 'M' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnEvo = document.getElementById('btn-chart-evo');\n      const btnSplit = document.getElementById('btn-chart-split');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'evolution') {\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-onorange-600 dark:text-onorange-400 shadow-sm transition';\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2022–FY2026E 年度净销售额与渠道演进';\n        subEl.textContent = 'DTC 直营与全渠道扩张驱动销售额从 CHF 1.2B 迅猛迈向 CHF 3.5B+';\n      } else {\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-onorange-600 dark:text-onorange-400 shadow-sm transition';\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'Q3 2026 单季产品线与渠道销售拆解';\n        subEl.textContent = '总净销售额 CHF 931.4M · DTC 占比 42.2% · 服装爆发 +38.7%';\n      }\n      initBizChart();\n    }\n\n    function initMoatRadar() {\n      const ctx = document.getElementById('onMoatRadar').getContext('2d');\n      const colors = getChartColors();\n\n      if (moatRadarInstance) moatRadarInstance.destroy();\n      moatRadarInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            'CloudTec® 专利缓震科技',\n            '全价销售与顶级毛利率',\n            '专业跑步与时尚破圈势能',\n            'DTC 渠道运营与直营掌控',\n            '全球明星与赛事代言矩阵'\n          ],\n          datasets: [\n            {\n              label: 'On (昂跑 ONON)',\n              data: [9.6, 9.8, 9.7, 9.2, 9.5],\n              borderColor: '#FF5500',\n              backgroundColor: 'rgba(255, 85, 0, 0.22)',\n              pointBackgroundColor: '#FF5500',\n              borderWidth: 2.5\n            },\n            {\n              label: 'Hoka (Deckers)',\n              data: [9.5, 8.8, 8.9, 8.2, 8.4],\n              borderColor: '#3B82F6',\n              backgroundColor: 'rgba(59, 130, 246, 0.14)',\n              pointBackgroundColor: '#3B82F6',\n              borderWidth: 1.8\n            },\n            {\n              label: 'Nike / Lululemon 阵营',\n              data: [8.5, 8.0, 8.2, 9.5, 9.2],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.12)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initValuationChart() {\n      const ctx = document.getElementById('onValuationChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (valuationChartInstance) valuationChartInstance.destroy();\n      valuationChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '全年净销售额 (CHF B)',\n              data: [1.22, 1.79, 2.29, 3.01, 3.52],\n              backgroundColor: 'rgba(255, 85, 0, 0.85)',\n              borderRadius: 5,\n              barThickness: 28,\n              yAxisID: 'y'\n            },\n            {\n              type: 'bar',\n              label: '毛利润 (CHF B)',\n              data: [0.73, 1.07, 1.41, 1.89, 2.38],\n              backgroundColor: 'rgba(6, 182, 212, 0.85)',\n              borderRadius: 5,\n              barThickness: 28,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '毛利率 (%)',\n              data: [60.0, 59.6, 61.5, 62.8, 67.5],\n              borderColor: '#F59E0B',\n              backgroundColor: '#F59E0B',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `${ctx.dataset.label}: CHF ${ctx.parsed.y}B`\n                  : `${ctx.dataset.label}: ${ctx.parsed.y}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 4.5,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => 'CHF ' + v + 'B' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 40,\n              max: 80,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + '%' }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initMoatRadar();\n      initValuationChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      initBizChart();\n      initMoatRadar();\n      initValuationChart();\n    });\n  </script>\n</body>\n</html>\n\"\"\"\n\nwith open(\"ONON.html\", \"w\", encoding=\"utf-8\") as f:\n    f.write(html_content)\nprint(\"Successfully generated ONON.html\")"};
